begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select ok(not has_function_privilege('anon', 'public.admin_update_account_profile(uuid,text,text,text)', 'EXECUTE'), 'anonymous callers cannot edit account profiles');
select ok(not has_function_privilege('anon', 'public.admin_update_user_profile(uuid,uuid,text,text)', 'EXECUTE'), 'anonymous callers cannot edit user profiles');
select ok(has_function_privilege('authenticated', 'public.admin_update_account_profile(uuid,text,text,text)', 'EXECUTE'), 'authenticated role reaches the guarded account RPC');
select ok(has_function_privilege('authenticated', 'public.admin_update_user_profile(uuid,uuid,text,text)', 'EXECUTE'), 'authenticated role reaches the guarded user RPC');
set local role authenticated;
select set_config('request.jwt.claim.sub', '10000000-0000-4000-8000-000000000010', true);
select set_config('request.jwt.claims', '{"sub":"10000000-0000-4000-8000-000000000010","aal":"aal2","role":"authenticated"}', true);
select throws_ok($$select public.admin_update_account_profile('20000000-0000-4000-8000-000000000001','Unauthorized','Europe/Moscow','Profile editing test owner access')$$,'42501','Superadmin access required','account owner cannot edit through administrative RPC');
select throws_ok($$select public.admin_update_user_profile('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000011','Unauthorized','Profile editing test owner access')$$,'42501','Superadmin access required','account owner cannot edit users through administrative RPC');
select set_config('request.jwt.claim.sub', '10000000-0000-4000-8000-000000000001', true);
select set_config('request.jwt.claims', '{"sub":"10000000-0000-4000-8000-000000000001","aal":"aal1","role":"authenticated"}', true);
select throws_ok($$select public.admin_update_account_profile('20000000-0000-4000-8000-000000000001','Unauthorized','Europe/Moscow','Profile editing test without MFA')$$,'42501','MFA verification required','single-factor admin cannot update account');
select throws_ok($$select public.admin_update_user_profile('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000011','Unauthorized','Profile editing test without MFA')$$,'42501','MFA verification required','single-factor admin cannot update user');
select set_config('request.jwt.claims', '{"sub":"10000000-0000-4000-8000-000000000001","aal":"aal2","role":"authenticated"}', true);
select throws_ok($$select public.admin_update_account_profile('20000000-0000-4000-8000-000000000001','  ','Europe/Moscow','Profile editing invalid name test')$$,'22023','Invalid account name','empty account name is rejected');
select throws_ok($$select public.admin_update_account_profile('20000000-0000-4000-8000-000000000001','Alpha renamed','Unknown/Zone','Profile editing invalid timezone test')$$,'22023','Invalid timezone','invalid timezone is rejected');
select throws_ok($$select public.admin_update_user_profile('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000011','Other account','Profile editing wrong account test')$$,'23503','Account user not found','user edit is scoped to a real membership');
select throws_ok($$select public.admin_update_user_profile('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000011',' ','Profile editing empty user name test')$$,'22023','Invalid user name','blank user name is rejected');
select lives_ok($$select public.admin_update_account_profile('20000000-0000-4000-8000-000000000001','  Alpha renamed  ','Asia/Yekaterinburg','Редактирование аккаунта администратором')$$,'verified administrator can edit account name and timezone');
select lives_ok($$select public.admin_update_user_profile('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000011','  Editor renamed  ','Редактирование пользователя администратором')$$,'verified administrator can edit user display name');
reset role;
select is((select name from public.accounts where id='20000000-0000-4000-8000-000000000001'),'Alpha renamed','account name is saved and trimmed');
select is((select timezone from public.accounts where id='20000000-0000-4000-8000-000000000001'),'Asia/Yekaterinburg','timezone is saved');
select is((select slug from public.accounts where id='20000000-0000-4000-8000-000000000001'),'alpha-studio','account URL remains unchanged');
select is((select owner_user_id from public.accounts where id='20000000-0000-4000-8000-000000000001'),'10000000-0000-4000-8000-000000000010'::uuid,'ownership remains unchanged');
select is((select full_name from public.profiles where id='10000000-0000-4000-8000-000000000011'),'Editor renamed','user name is saved and trimmed');
select is((select role::text from public.account_members where account_id='20000000-0000-4000-8000-000000000001' and user_id='10000000-0000-4000-8000-000000000011'),'editor','membership role remains unchanged');
select is((select role::text from public.profiles where id='10000000-0000-4000-8000-000000000011'),'account_user','platform role remains unchanged');
select is((select metadata_safe->'before'->>'name' from private.admin_audit_logs where action='admin.account.profile.update' order by id desc limit 1),'Alpha Studio','audit records account before state');
select is((select metadata_safe->'after'->>'name' from private.admin_audit_logs where action='admin.account.profile.update' order by id desc limit 1),'Alpha renamed','audit records account after state');
select is((select metadata_safe->'after'->>'fullName' from private.admin_audit_logs where action='admin.user.profile.update' order by id desc limit 1),'Editor renamed','audit records profile after state');
select * from finish();
rollback;
